# 레코드 접근 4겹: 조직 기본값(OWD) -> 역할 계층 -> 공유 규칙 -> 수동 공유. 위 겹은 넓히기만 한다.
roles = {"영업1팀원": "영업1팀장", "영업2팀원": "영업2팀장", "영업1팀장": "영업본부장", "영업2팀장": "영업본부장"}


def above(role):
    out = []
    while role in roles:
        role = roles[role]
        out.append(role)
    return out


def can_read(user_role, rec, owd="Private", sharing_rules=(), manual=()):
    if owd in ("Public Read Only", "Public Read/Write"):
        return "OWD"
    if user_role == rec["owner_role"]:
        return "소유자"
    if user_role in above(rec["owner_role"]):
        return "역할 계층"
    for rule in sharing_rules:
        if rec["region"] == rule["region"] and user_role in rule["to"]:
            return "공유 규칙"
    if user_role in manual:
        return "수동 공유"
    return "못 봄"


rec = {"name": "A사 영업기회", "owner_role": "영업1팀원", "region": "수도권"}
rules = [{"region": "수도권", "to": {"영업2팀장"}}]
for r in ["영업1팀장", "영업본부장", "영업2팀원", "영업2팀장"]:
    print(r, "->", can_read(r, rec, sharing_rules=rules))
print("영업2팀원(수동 공유 후) ->", can_read("영업2팀원", rec, sharing_rules=rules, manual={"영업2팀원"}))

# Apex 트리거가 한 번에 받는 200건을 처리할 때, 한 건마다 조회하면 SOQL 한도(동기 100회)를 넘는다.
SOQL_LIMIT = 100
accounts = {f"A{i}": {"tier": "VIP" if i % 3 == 0 else "STD"} for i in range(200)}
orders = [{"id": f"O{i}", "account": f"A{i}"} for i in range(200)]


def per_record(batch):
    queries = 0
    for o in batch:
        queries += 1  # SELECT ... WHERE Id = :o.account
        if queries > SOQL_LIMIT:
            return f"LimitException: Too many SOQL queries: {queries}"
        o["tier"] = accounts[o["account"]]["tier"]
    return f"ok, queries={queries}"


def bulk(batch):
    ids = {o["account"] for o in batch}  # 한 번에 모은다
    found = {k: accounts[k] for k in ids}  # SELECT ... WHERE Id IN :ids (1회)
    for o in batch:
        o["tier"] = found[o["account"]]["tier"]
    return "ok, queries=1"


print(per_record([dict(o) for o in orders]))
print(bulk([dict(o) for o in orders]))
